INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('kitchen-court', 1, 'Kitchen Court', 'In the Delacroix-Huang house every family dispute goes to trial at the kitchen table, because Mom is a real small claims judge and Grandma is a retired referee.', 'Every dispute in this house goes to trial at the kitchen table. Mom presides. Grandma referees. The six-year-old is the bailiff. Verdicts end in dessert.', 'Comedy', 'Family', '22 min', NULL, 90, 28, 'trailer', 1);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('long-route', 2, 'Long Route', 'Six kids at the far end of the county''s last long school bus route spend 48 minutes together twice a day, and that bus is where everything happens.', 'Six kids, one bus, forty-eight minutes each way. The back row runs a parliament. The driver hears everything. School is the thing that happens between rides.', 'Comedy', 'Family', '22 min', NULL, 90, 205, 'trailer', 2);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('recent-history-society', 3, 'Recent History Society', 'A sketch show about a historical reenactment society that only reenacts things that happened last week, in full costume, with total seriousness.', 'A society of reenactors who only reenact last week. Full costume. Total seriousness. A ten-year-old plays the fire hydrant with too much feeling.', 'Variety', 'Family', '12 min', NULL, 70, 330, 'premiere', 3);
INSERT OR REPLACE INTO shows (id, slot, title, logline, blurb, genre_label, rating_label, runtime_label, trailer_url, trailer_seconds, poster_hue, status, sort_order) VALUES ('the-night-desk', 4, 'The Night Desk', 'The overnight clerk at a 24-hour hardware store hears the story behind every item that comes back to the returns desk, and every return has a spooky reason.', 'After hours at the hardware store, the returns desk takes back the things nobody wants. Some of them hum. Some of them ring. Marguerite needs two receipts.', 'Anthology', 'Family', '18 min', NULL, 110, 262, 'trailer', 4);
